"use client";

import Link from "next/link";
import { useEffect, useMemo, useState, type ChangeEvent, type FormEvent } from "react";
import {
  COVERAGE_TARGETS,
  EXTERNAL_REFERENCE_REMINDER,
  MODULES,
  STARTER_ITEMS,
  STARTER_SOURCES,
  findSourcesByCategory,
  getCoverageCounts,
  getVocabularyForKanji,
  parseStudyImport,
  mergeStudyItems,
  type ImportedStudyItem,
  type JlptN2Source,
  type JlptN2SourceCategory,
} from "@/lib/jlpt-n2-curriculum";

const ITEMS_KEY = "jlpt-n2-study-items-v1";
const SOURCES_KEY = "jlpt-n2-source-library-v1";
const PROGRESS_KEY = "jlpt-n2-progress-v2";
const MISTAKES_KEY = "jlpt-n2-mistakes-v1";
const DAILY_KEY = "jlpt-n2-daily-v1";
const EXAM_ATTEMPTS_KEY = "jlpt-n2-exam-attempts-v1";
const SETTINGS_KEY = "jlpt-n2-settings-v1";

type AppView = "dashboard" | "today" | "sources" | "settings" | "exam-mode" | "repair-plan" | JlptN2SourceCategory;
type StudyMode = "cards" | "flashcards" | "quiz";
type StatusFilter = "all" | "known" | "unknown" | "due";
type Progress = { status: "new" | "known" | "unknown"; srsLevel: number; dueDate: string; right: number; wrong: number };
type Mistake = { id: string; itemId: string; module: JlptN2SourceCategory; prompt: string; expected: string; answer: string; createdAt: string; explanation_np?: string; related_vocab?: string; related_kanji?: string; related_grammar?: string; mistake_reason?: string; retry_status?: string };
type Daily = { lastFinishedDate: string; streak: number; finishedDates: string[] };
type ExamAttempt = { id: string; date: string; mode: "full" | "mini"; languageScore: number; readingScore: number; listeningScore: number; total: number; pass: boolean; target150: boolean; weakestSection: string; notes: string };
type ExamSettings = { examWeekMode: boolean; strictMode: boolean; daysUntilExam: string; lastBackupReminderDate: string };
type SourceDraft = Omit<JlptN2Source, "id">;
type ImportPreview = { rows: ImportedStudyItem[]; errors: string[] };
type WeakAnalysis = ReturnType<typeof analyzeWeakPoints>;

const SOURCE_LIBRARY = buildSourceLibrary();
const emptySource: SourceDraft = { name: "", category: "vocabulary", level: "N2", url: "", notes: "", best_use: "", favorite: false, externalOnly: true, hasImportedPersonalNotes: false, lastStudiedDate: "", usefulnessRating: 3 };
const emptyItem: ImportedStudyItem = { id: "", module: "vocabulary", term: "", reading: "", meaning: "", explanation: "", example: "", source_name: "Manual entry", source_url: "", source_type: "user-notes", copyright_status: "created-by-user", user_notes: "", created_by_user: true };

const nav: Array<{ label: string; href: string; view: AppView }> = [
  { label: "Dashboard", href: "/jlpt-n2", view: "dashboard" },
  { label: "今日の勉強 / आज", href: "/jlpt-n2/today", view: "today" },
  { label: "語彙 / शब्द", href: "/jlpt-n2/vocabulary", view: "vocabulary" },
  { label: "漢字 / कान्जी", href: "/jlpt-n2/kanji", view: "kanji" },
  { label: "文法 / Grammar", href: "/jlpt-n2/grammar", view: "grammar" },
  { label: "読解 / Reading", href: "/jlpt-n2/reading", view: "reading" },
  { label: "聴解 / Listening", href: "/jlpt-n2/listening", view: "listening" },
  { label: "模試 / Mock", href: "/jlpt-n2/mock-tests", view: "mock test" },
  { label: "Exam Mode", href: "/jlpt-n2/exam-mode", view: "exam-mode" },
  { label: "Repair Plan", href: "/jlpt-n2/repair-plan", view: "repair-plan" },
  { label: "間違いノート / गल्ती", href: "/jlpt-n2/mistakes", view: "mistakes" },
  { label: "復習 / Review", href: "/jlpt-n2/srs", view: "srs" },
  { label: "Sources", href: "/jlpt-n2/sources", view: "sources" },
  { label: "弱点 / Settings", href: "/jlpt-n2/settings", view: "settings" },
];

const templates: Partial<Record<JlptN2SourceCategory, string>> = {
  vocabulary: "term,word,reading,kanji_form,kana_form,meaning_np,meaning_en,part_of_speech,jlpt_estimated_level,priority_score,related_kanji,example_jp,example_np,collocations,similar_words,common_mistake,tags,source_type,source_name,source_url,copyright_status,user_notes,created_by_user",
  kanji: "term,kanji,onyomi,kunyomi,meaning_np,meaning_en,radicals,similar_kanji,common_mistakes,example,example_words,n2_priority_words,jlpt_estimated_level,source_type,source_name,source_url,copyright_status,user_notes,created_by_user",
  grammar: "term,pattern,meaning_np,meaning_en,formation,nuance,register,usage_context,similar_patterns,common_mistake,explanation_np,example_jp,example_np,quiz_items,jlpt_estimated_level,source_type,source_name,source_url,copyright_status,user_notes,created_by_user",
  reading: "term,title,reading_type,passage_type,difficulty,estimated_time_minutes,target_time_seconds,timer_target,example_jp,passage_jp,question,questions,correct_answer,correct_answers,explanation_np,vocabulary_notes,grammar_notes,why_wrong,jlpt_estimated_level,source_type,source_name,source_url,copyright_status,user_notes,created_by_user",
  listening: "term,title,audio_url,audio_url_optional,weakness_category,conversation_type,difficulty,question_type,example_jp,script_jp,question,questions,correct_answer,correct_answers,explanation_np,key_vocabulary,key_vocab,key_grammar,dictation_text,shadowing_checklist,jlpt_estimated_level,source_type,source_name,source_url,copyright_status,user_notes,created_by_user",
  "mock test": "term,language_score,reading_score,listening_score,explanation,explanation_np,mini_mock_items,weak_section_repair,score_strategy,user_notes,source_type,created_by_user",
  mistakes: "term,module,question,answer,correct_answer,explanation_np,related_vocab,related_kanji,related_grammar,mistake_reason,retry_status",
  srs: "term,module,reading,meaning,source_name,source_url,copyright_status,user_notes,created_by_user",
};

export default function JlptN2App({ initialView = "dashboard" }: { initialView?: AppView }) {
  const [items, setItems] = useState<ImportedStudyItem[]>(STARTER_ITEMS);
  const [sources, setSources] = useState<JlptN2Source[]>(SOURCE_LIBRARY);
  const [progress, setProgress] = useState<Record<string, Progress>>({});
  const [mistakes, setMistakes] = useState<Mistake[]>([]);
  const [daily, setDaily] = useState<Daily>({ lastFinishedDate: "", streak: 0, finishedDates: [] });
  const [attempts, setAttempts] = useState<ExamAttempt[]>([]);
  const [settings, setSettings] = useState<ExamSettings>({ examWeekMode: false, strictMode: true, daysUntilExam: "", lastBackupReminderDate: "" });
  const [view, setView] = useState<AppView>(initialView);
  const [module, setModuleState] = useState<JlptN2SourceCategory>(isModule(initialView) ? initialView : "vocabulary");
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<StatusFilter>("all");
  const [mode, setMode] = useState<StudyMode>("cards");
  const [selectedId, setSelectedId] = useState("");
  const [answer, setAnswer] = useState("");
  const [message, setMessage] = useState("");
  const [showScript, setShowScript] = useState(false);
  const [dictation, setDictation] = useState("");
  const [timerStartedAt, setTimerStartedAt] = useState<number | null>(null);
  const [readingSeconds, setReadingSeconds] = useState(0);
  const [importModule, setImportModule] = useState<JlptN2SourceCategory>("vocabulary");
  const [importText, setImportText] = useState("");
  const [preview, setPreview] = useState<ImportPreview>({ rows: [], errors: [] });
  const [restoreText, setRestoreText] = useState("");
  const [sourceDraft, setSourceDraft] = useState<SourceDraft>(emptySource);
  const [editingSourceId, setEditingSourceId] = useState<string | null>(null);
  const [itemDraft, setItemDraft] = useState<ImportedStudyItem>(emptyItem);
  const [editingItemId, setEditingItemId] = useState<string | null>(null);
  const [installState, setInstallState] = useState("PWA ready");
  const [hydrated, setHydrated] = useState(false);

  useEffect(() => { setView(initialView); if (isModule(initialView)) setModuleState(initialView); }, [initialView]);
  useEffect(() => {
    setItems(mergeStudyItems(readLocal<ImportedStudyItem[]>(ITEMS_KEY), STARTER_ITEMS));
    setSources(mergeSources(readLocal<JlptN2Source[]>(SOURCES_KEY), SOURCE_LIBRARY));
    setProgress(readLocal<Record<string, Progress>>(PROGRESS_KEY) ?? {});
    setMistakes(readLocal<Mistake[]>(MISTAKES_KEY) ?? []);
    setDaily(readLocal<Daily>(DAILY_KEY) ?? { lastFinishedDate: "", streak: 0, finishedDates: [] });
    setAttempts(readLocal<ExamAttempt[]>(EXAM_ATTEMPTS_KEY) ?? []);
    setSettings({ examWeekMode: false, strictMode: true, daysUntilExam: "", lastBackupReminderDate: "", ...(readLocal<ExamSettings>(SETTINGS_KEY) ?? {}) });
    if ("serviceWorker" in navigator) navigator.serviceWorker.register("/sw.js").then(() => setInstallState("Installable app shell active")).catch(() => setInstallState("Local data active"));
    setHydrated(true);
  }, []);
  useEffect(() => { if (hydrated) localStorage.setItem(ITEMS_KEY, JSON.stringify(items)); }, [hydrated, items]);
  useEffect(() => { if (hydrated) localStorage.setItem(SOURCES_KEY, JSON.stringify(sources)); }, [hydrated, sources]);
  useEffect(() => { if (hydrated) localStorage.setItem(PROGRESS_KEY, JSON.stringify(progress)); }, [hydrated, progress]);
  useEffect(() => { if (hydrated) localStorage.setItem(MISTAKES_KEY, JSON.stringify(mistakes)); }, [hydrated, mistakes]);
  useEffect(() => { if (hydrated) localStorage.setItem(DAILY_KEY, JSON.stringify(daily)); }, [hydrated, daily]);
  useEffect(() => { if (hydrated) localStorage.setItem(EXAM_ATTEMPTS_KEY, JSON.stringify(attempts)); }, [hydrated, attempts]);
  useEffect(() => { if (hydrated) localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); }, [hydrated, settings]);

  const counts = useMemo(() => getCoverageCounts(items), [items]);
  const activeItems = useMemo(() => filterItems(items, module, progress, search, filter), [filter, items, module, progress, search]);
  const selected = items.find((item) => item.id === selectedId) ?? activeItems[0];
  const srsQueue = useMemo(() => getSrsQueue(items, progress), [items, progress]);
  const weak = useMemo(() => analyzeWeakPoints(items, progress, mistakes, attempts), [items, progress, mistakes, attempts]);
  const readiness = useMemo(() => calcReadiness(items, progress, mistakes, attempts), [items, mistakes, progress, attempts]);
  const plan = useMemo(() => buildPlan(items, progress, mistakes, weak, settings), [items, mistakes, progress, weak, settings]);

  function switchModule(next: JlptN2SourceCategory) { setModuleState(next); setView(next); setMode("cards"); setItemDraft({ ...emptyItem, module: next }); }
  function saveItem(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const row = { ...itemDraft, id: editingItemId ?? "user-" + itemDraft.module + "-" + Date.now(), module: itemDraft.module || module, term: itemDraft.term.trim(), created_by_user: true, copyright_status: itemDraft.copyright_status || "created-by-user" };
    if (!row.term) return;
    setItems((current) => editingItemId ? current.map((item) => item.id === editingItemId ? row : item) : [row, ...current]);
    setEditingItemId(null); setItemDraft({ ...emptyItem, module });
  }
  function editItem(item: ImportedStudyItem) { setEditingItemId(item.id); setItemDraft({ ...emptyItem, ...item }); setModuleState(item.module); setView(item.module); }
  function deleteItem(id: string) { setItems((current) => current.filter((item) => item.id !== id)); setMistakes((current) => current.filter((mistake) => mistake.itemId !== id)); setProgress((current) => { const next = { ...current }; delete next[id]; return next; }); }
  function grade(item: ImportedStudyItem, correct: boolean, userAnswer = answer) {
    setProgress((current) => { const old = getProgress(item.id, current); const level = correct ? Math.min(6, old.srsLevel + 1) : Math.max(0, old.srsLevel - 1); return { ...current, [item.id]: { status: correct ? "known" : "unknown", srsLevel: level, dueDate: addDaysIso(correct ? srsDelay(level) : 1), right: old.right + (correct ? 1 : 0), wrong: old.wrong + (correct ? 0 : 1) } }; });
    if (!correct) setMistakes((current) => [{ id: "mistake-" + Date.now(), itemId: item.id, module: item.module, prompt: item.question || item.term, expected: item.correct_answer || expected(item), answer: userAnswer || "Marked wrong", createdAt: new Date().toISOString(), explanation_np: item.explanation_np || item.explanation || "गल्तीको कारण आफ्नै नोटमा थप्नुहोस्।", related_vocab: item.module === "vocabulary" ? item.term : item.user_notes || "", related_kanji: item.module === "kanji" ? item.term : "", related_grammar: item.module === "grammar" ? item.term : "", mistake_reason: item.mistake_reason || "needs review", retry_status: item.retry_status || "new" }, ...current]);
    setMessage(correct ? "Correct. SRS moved forward." : "Saved to mistakes and SRS due tomorrow."); setAnswer("");
  }
  function extractWordToSrs(word: string, sourceItem: ImportedStudyItem) {
    const clean = word.trim();
    if (!clean) return;
    const existing = items.find((item) => item.module === "vocabulary" && item.term === clean);
    if (existing) { grade(existing, false, "extracted unknown"); return; }
    const row: ImportedStudyItem = { id: "extracted-vocabulary-" + Date.now() + "-" + clean, module: "vocabulary", term: clean, reading: "", meaning: "Unknown extracted from reading", explanation: "Add your own legal dictionary note or Nepali explanation.", example: sourceItem.example || sourceItem.term, source_name: sourceItem.source_name || "Reading extraction", source_url: sourceItem.source_url || "", source_type: "user-reading-extraction", copyright_status: "created-by-user", user_notes: "Extracted from " + sourceItem.term, created_by_user: true };
    setItems((current) => [row, ...current]);
    grade(row, false, "extracted unknown");
  }
  function check(item: ImportedStudyItem) { const ok = Boolean(answer.trim()) && expected(item).toLowerCase().includes(answer.trim().toLowerCase()); grade(item, ok, answer); }
  function previewImport(event: FormEvent<HTMLFormElement>) { event.preventDefault(); try { const rows = parseStudyImport(importText, importModule); setPreview({ rows, errors: validateRows(rows, importModule) }); } catch (error) { setPreview({ rows: [], errors: [error instanceof Error ? error.message : "Could not parse import data."] }); } }
  function savePreview() { if (!preview.rows.length || preview.errors.length) return; setItems((current) => [...preview.rows, ...current]); setImportText(""); setPreview({ rows: [], errors: [] }); }
  function saveSource(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!sourceDraft.name.trim()) return; setSources((current) => editingSourceId ? current.map((source) => source.id === editingSourceId ? { ...sourceDraft, id: source.id } : source) : [{ ...sourceDraft, id: "source-" + Date.now() }, ...current]); setEditingSourceId(null); setSourceDraft(emptySource); }
  function finishToday() { const now = todayIso(); if (daily.lastFinishedDate === now) return; const yesterday = addDaysIso(-1); setDaily((current) => ({ lastFinishedDate: now, streak: current.lastFinishedDate === yesterday ? current.streak + 1 : 1, finishedDates: Array.from(new Set([now, ...current.finishedDates])).slice(0, 90) })); }
  function saveExamAttempt(scores: { language: number; reading: number; listening: number; notes: string }) { const total = scores.language + scores.reading + scores.listening; const pass = total >= 90 && scores.language >= 19 && scores.reading >= 19 && scores.listening >= 19; const target150 = total >= 150 && scores.language >= 45 && scores.reading >= 45 && scores.listening >= 45; const weakestSection = weakestFromScores(scores.language, scores.reading, scores.listening); const row: ExamAttempt = { id: "exam-" + Date.now(), date: new Date().toISOString(), mode: "full", languageScore: scores.language, readingScore: scores.reading, listeningScore: scores.listening, total, pass, target150, weakestSection, notes: scores.notes }; setAttempts((current) => [row, ...current].slice(0, 80)); }
  function exportBackup() { downloadText("jlpt-n2-full-backup.json", JSON.stringify({ items, sources, progress, mistakes, daily, attempts, settings }, null, 2)); setSettings((current) => ({ ...current, lastBackupReminderDate: todayIso() })); }
  function restoreBackup() { try { const parsed = JSON.parse(restoreText) as Partial<{ items: ImportedStudyItem[]; sources: JlptN2Source[]; progress: Record<string, Progress>; mistakes: Mistake[]; daily: Daily; attempts: ExamAttempt[]; settings: ExamSettings }>; if (!window.confirm("Restore this backup? Current local browser progress will be replaced by the backup data.")) return; if (parsed.items) setItems(mergeStudyItems(parsed.items, STARTER_ITEMS)); if (parsed.sources) setSources(mergeSources(parsed.sources, SOURCE_LIBRARY)); if (parsed.progress) setProgress(parsed.progress); if (parsed.mistakes) setMistakes(parsed.mistakes); if (parsed.daily) setDaily(parsed.daily); if (parsed.attempts) setAttempts(parsed.attempts); if (parsed.settings) setSettings({ ...settings, ...parsed.settings }); setRestoreText(""); setMessage("Backup restored."); } catch { setMessage("Could not restore backup. Check that the JSON is a full backup export."); } }
  function printReport(title: string, rows: Array<ImportedStudyItem | Mistake>) { const html = rows.slice(0, 100).map((row) => "term" in row ? "<li><b>" + esc(row.term) + "</b> " + esc(row.reading ?? "") + " " + esc(row.meaning ?? row.explanation ?? "") + "</li>" : "<li><b>" + esc(row.prompt) + "</b> expected: " + esc(row.expected) + " answer: " + esc(row.answer) + "</li>").join(""); const win = window.open("", "_blank", "noopener,noreferrer"); if (!win) return; win.document.write("<!doctype html><title>" + esc(title) + "</title><style>body{font-family:system-ui;padding:32px;line-height:1.5}h1{color:#1d5c3b}li{margin:8px 0}</style><h1>" + esc(title) + "</h1><p>" + EXTERNAL_REFERENCE_REMINDER + "</p><ol>" + html + "</ol>"); win.document.close(); win.print(); }

  return <main className="jlpt-n2-app min-h-screen bg-[#f7faf8] text-[#162018]"><div className="mx-auto flex min-h-screen w-full max-w-7xl flex-col px-4 py-4 pb-24 sm:px-6 lg:px-8"><Header activeView={view} installState={installState} /><Reminder />{settings.examWeekMode ? <ExamWeekBanner /> : null}<BackupReminder settings={settings} onBackup={exportBackup} />
    {view === "dashboard" ? <Dashboard counts={counts} readiness={readiness} srsCount={srsQueue.length} weakest={readiness.weakest} weak={weak} onPrint={() => printReport("Mock result report", items)} /> : null}
    {view === "today" ? <TodayPage plan={plan} srsQueue={srsQueue} mistakes={mistakes} daily={daily} settings={settings} weak={weak} onGrade={grade} onFinish={finishToday} onPrint={() => printReport("Daily JLPT N2 study plan", [...plan.all, ...srsQueue])} /> : null}
    {view === "exam-mode" ? <ExamModePage attempts={attempts} settings={settings} weak={weak} readiness={readiness} onSettings={setSettings} onSaveAttempt={saveExamAttempt} /> : null}
    {view === "repair-plan" ? <RepairPlanPage weak={weak} settings={settings} plan={plan} onPrint={() => printReport("7-day JLPT N2 repair plan", plan.all)} /> : null}
    {isModule(view) ? <ModulePage module={module} items={activeItems} allItems={items} sources={findSourcesByCategory(sources, module)} progress={progress} selected={selected} mode={mode} search={search} filter={filter} answer={answer} message={message} itemDraft={itemDraft} editingItemId={editingItemId} showScript={showScript} dictation={dictation} readingSeconds={readingSeconds} timerStartedAt={timerStartedAt} onSetModule={switchModule} onSetMode={setMode} onSearch={setSearch} onFilter={setFilter} onSelect={setSelectedId} onAnswer={setAnswer} onCheck={check} onGrade={grade} onExtractWord={extractWordToSrs} onDraft={setItemDraft} onSaveItem={saveItem} onEditItem={editItem} onDeleteItem={deleteItem} onToggleScript={() => setShowScript((current) => !current)} onDictation={setDictation} onStartTimer={() => { setTimerStartedAt(Date.now()); setReadingSeconds(0); }} onStopTimer={() => { if (timerStartedAt) setReadingSeconds(Math.round((Date.now() - timerStartedAt) / 1000)); setTimerStartedAt(null); }} onPrintWeak={() => printReport("Weak " + module + " list", activeItems.filter((item) => getProgress(item.id, progress).status === "unknown"))} /> : null}
    {view === "mistakes" ? <MistakesPage mistakes={mistakes} items={items} onPrint={() => printReport("Mistake review report", mistakes)} /> : null}
    {view === "sources" ? <SourcesPage sources={sources} draft={sourceDraft} editingId={editingSourceId} onDraft={setSourceDraft} onSave={saveSource} onEdit={(source) => { setEditingSourceId(source.id); setSourceDraft({ name: source.name, category: source.category, level: source.level, url: source.url, notes: source.notes, best_use: source.best_use || "", favorite: Boolean(source.favorite), externalOnly: source.externalOnly, hasImportedPersonalNotes: source.hasImportedPersonalNotes, lastStudiedDate: source.lastStudiedDate, usefulnessRating: source.usefulnessRating }); }} onDelete={(id) => setSources((current) => current.filter((source) => source.id !== id))} onCancel={() => { setEditingSourceId(null); setSourceDraft(emptySource); }} /> : null}
    {view === "settings" ? <SettingsPage importModule={importModule} importText={importText} preview={preview} settings={settings} message={message} restoreText={restoreText} onSettings={setSettings} onImportModule={setImportModule} onImportText={setImportText} onFile={(event) => event.target.files?.[0]?.text().then(setImportText)} onPreview={previewImport} onSavePreview={savePreview} onTemplate={(next) => downloadText(next + ".csv", (templates[next] ?? templates.vocabulary) + "\n")} onGenerate={() => setItems((current) => [...buildOriginalBatch(current.length), ...current])} onPrintGrammar={() => printReport("Grammar review sheet", items.filter((item) => item.module === "grammar"))} onPrintMock={() => printReport("Mock result report", items)} onBackup={exportBackup} onRestoreText={setRestoreText} onRestore={restoreBackup} /> : null}
  <MobileBottomNav activeView={view} /></div></main>;
}

function MobileBottomNav({ activeView }: { activeView: AppView }) { const mobileNav = nav.filter((item) => ["dashboard", "today", "vocabulary", "exam-mode", "repair-plan"].includes(String(item.view))); return <nav className="fixed inset-x-0 bottom-0 z-30 grid grid-cols-5 gap-1 border-t border-[#cfd8cf] bg-white/95 px-2 py-2 text-center text-[10px] font-bold text-[#1d5c3b] shadow-lg sm:hidden">{mobileNav.map((item) => <Link key={item.href} className={["rounded-md px-1 py-2", activeView === item.view ? "bg-[#1d5c3b] text-white" : "bg-[#f8fbf8]"].join(" ")} href={item.href}>{item.label}</Link>)}</nav>; }
function Header({ activeView, installState }: { activeView: AppView; installState: string }) { return <header className="rounded-lg border border-[#cfd8cf] bg-white px-4 py-4 shadow-sm sm:px-5"><p className="text-xs font-bold uppercase tracking-[0.16em] text-[#4d745d]">Source-aware N2 150+ curriculum</p><h1 className="mt-2 text-2xl font-bold tracking-tight text-[#102015] sm:text-3xl">JLPT N2 Study System</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-[#4b5f50]">Daily study, SRS, mistakes, timed exam simulation, repair plans, imports, and source links without copying external content.</p><nav className="mt-4 flex gap-2 overflow-x-auto pb-1" aria-label="JLPT N2 navigation">{nav.map((item) => <Link key={item.href} className={["shrink-0 rounded-md border px-3 py-2 text-sm font-bold", activeView === item.view ? "border-[#1d5c3b] bg-[#1d5c3b] text-white" : "border-[#b9c8bc] bg-white text-[#1d5c3b]"].join(" ")} href={item.href}>{item.label}</Link>)}</nav><div className="mt-4 grid gap-2 text-sm text-[#435548] sm:grid-cols-3"><Pill label="Mobile" value="iPhone / Android ready" /><Pill label="Desktop" value="Chrome / Safari ready" /><Pill label="PWA" value={installState} /></div></header>; }
function Reminder() { return <div className="mt-4 rounded-lg border border-[#d9d1a6] bg-[#fffbea] px-4 py-3 text-sm font-semibold leading-6 text-[#5d4c12]">{EXTERNAL_REFERENCE_REMINDER}</div>; }
function ExamWeekBanner() { return <div className="mt-4 rounded-lg border border-[#abd0bc] bg-[#eef8f1] px-4 py-3 text-sm font-semibold leading-6 text-[#1d5c3b]">Exam Week Mode is on: review-first schedule, timed reading daily, listening daily, mistake notebook daily, light vocab/kanji, and mock correction.</div>; }
function BackupReminder({ settings, onBackup }: { settings: ExamSettings; onBackup: () => void }) { const due = !settings.lastBackupReminderDate || daysBetween(settings.lastBackupReminderDate, todayIso()) >= 7; return <div className={["mt-4 rounded-lg border px-4 py-3 text-sm leading-6", due ? "border-[#d9d1a6] bg-[#fffbea] text-[#5d4c12]" : "border-[#d9e2da] bg-white text-[#58665c]"].join(" ")}><div className="flex flex-wrap items-center justify-between gap-2"><span><strong>Weekly backup reminder:</strong> progress is stored in this browser. Export before clearing browser data or changing devices.</span><button className="rounded-md bg-[#1d5c3b] px-3 py-2 text-xs font-bold text-white" type="button" onClick={onBackup}>Export Full Backup</button></div></div>; }
function Pill({ label, value }: { label: string; value: string }) { return <div className="rounded-md border border-[#d8e0d8] bg-[#f8fbf8] px-3 py-2"><span className="font-bold text-[#1d5c3b]">{label}:</span> {value}</div>; }
function Panel({ title, eyebrow, children }: { title: string; eyebrow?: string; children: React.ReactNode }) { return <section className="rounded-lg border border-[#cfd8cf] bg-white p-4 shadow-sm">{eyebrow ? <p className="text-xs font-bold uppercase tracking-[0.16em] text-[#4d745d]">{eyebrow}</p> : null}<h2 className={eyebrow ? "mt-1 text-xl font-bold" : "text-xl font-bold"}>{title}</h2><div className="mt-3">{children}</div></section>; }
function Dashboard({ counts, readiness, srsCount, weakest, weak, onPrint }: { counts: Record<string, number>; readiness: ReturnType<typeof calcReadiness>; srsCount: number; weakest: string; weak: WeakAnalysis; onPrint: () => void }) { return <div className="grid flex-1 gap-4 py-4 lg:grid-cols-[minmax(0,1fr)_360px]"><section className="space-y-4"><Coverage counts={counts} /><Readiness readiness={readiness} /><ScoreAnalytics weak={weak} readiness={readiness} /><SevenDay weak={weak} /></section><aside className="space-y-4"><Panel title="Daily actions"><div className="grid gap-2"><Link className="rounded-md bg-[#1d5c3b] px-4 py-3 text-center text-sm font-bold text-white" href="/jlpt-n2/today">Start Daily Study</Link><Link className="rounded-md border border-[#b9c8bc] px-4 py-3 text-center text-sm font-bold text-[#1d5c3b]" href="/jlpt-n2/exam-mode">Open Exam Mode</Link><Link className="rounded-md border border-[#b9c8bc] px-4 py-3 text-center text-sm font-bold text-[#1d5c3b]" href="/jlpt-n2/repair-plan">View Repair Plan</Link><button className="rounded-md border border-[#b9c8bc] px-4 py-3 text-sm font-bold text-[#1d5c3b]" type="button" onClick={onPrint}>Print Mock Result Report</button><p className="text-sm text-[#58665c]">{srsCount} SRS reviews are due today. Weakest module: {weakest}.</p></div></Panel><Panel title="Study modules"><div className="grid grid-cols-2 gap-2">{nav.slice(2, 13).map((item) => <Link key={item.href} className="rounded-md border border-[#d4ded6] px-3 py-2 text-sm font-bold text-[#1d5c3b]" href={item.href}>{item.label}</Link>)}</div></Panel></aside></div>; }
function Coverage({ counts }: { counts: Record<string, number> }) { return <Panel eyebrow="150+ Coverage Tracker" title="Practical N2 targets"><div className="grid gap-3 md:grid-cols-2">{COVERAGE_TARGETS.map((target) => { const current = counts[target.currentKey] ?? 0; const pct = Math.min(100, Math.round((current / target.numericTarget) * 100)); return <div key={target.id} className="rounded-md border border-[#d9e2da] bg-[#fbfdfb] p-3"><div className="flex justify-between gap-3 text-sm"><strong>{target.label}</strong><span>{current}/{target.target}</span></div><div className="mt-2 h-2 rounded-full bg-[#e1e9e2]"><div className="h-2 rounded-full bg-[#1d5c3b]" style={{ width: pct + "%" }} /></div></div>; })}</div></Panel>; }
function Readiness({ readiness }: { readiness: ReturnType<typeof calcReadiness> }) { return <Panel eyebrow="150点目標 / 150+ लक्ष्य" title="Estimated score"><div className="grid gap-3 sm:grid-cols-4"><Score label="Language Knowledge" value={readiness.language} target="52/60" /><Score label="Reading" value={readiness.reading} target="50/60" /><Score label="Listening" value={readiness.listening} target="48/60" /><Score label="Total" value={readiness.total} target="150/180" /></div><p className="mt-3 text-sm font-semibold text-[#5d4c12]">Weakest module: {readiness.weakest}</p></Panel>; }
function Score({ label, value, target }: { label: string; value: number; target: string }) { return <div className="rounded-md border border-[#d9e2da] bg-[#fbfdfb] p-3"><p className="text-xs font-bold uppercase tracking-[0.1em] text-[#4d745d]">{label}</p><p className="mt-2 text-3xl font-bold text-[#1d5c3b]">{value}</p><p className="text-xs text-[#617069]">Target {target}</p></div>; }
function ScoreAnalytics({ weak, readiness }: { weak: WeakAnalysis; readiness: ReturnType<typeof calcReadiness> }) { return <Panel eyebrow="Score trend analytics" title="150+ intelligence"><div className="grid gap-3 sm:grid-cols-3"><Metric label="Last 5 average" value={weak.lastFiveAverage ? String(weak.lastFiveAverage) + "/180" : "No mock yet"} /><Metric label="Best score" value={weak.bestScore ? String(weak.bestScore) + "/180" : "No mock yet"} /><Metric label="Worst section" value={weak.worstSection} /><Metric label="Section trend" value={weak.sectionTrend} /><Metric label="150+ readiness" value={weak.readinessPercent + "%"} /><Metric label="Estimated range" value={Math.max(0, readiness.total - 8) + "-" + Math.min(180, readiness.total + 8)} /></div></Panel>; }
function Metric({ label, value }: { label: string; value: string }) { return <div className="rounded-md border border-[#d9e2da] bg-[#fbfdfb] p-3"><p className="text-xs font-bold uppercase tracking-[0.1em] text-[#4d745d]">{label}</p><p className="mt-1 text-lg font-bold text-[#1d5c3b]">{value}</p></div>; }
function SevenDay({ weak }: { weak: WeakAnalysis }) { return <Panel eyebrow="Recommended next 7 days" title="Repair direction"><ol className="grid gap-2 text-sm leading-6 text-[#334238]">{buildSevenDayPlan(weak).map((line) => <li key={line} className="rounded-md border border-[#d9e2da] bg-[#fbfdfb] p-2">{line}</li>)}</ol></Panel>; }

function TodayPage({ plan, srsQueue, mistakes, daily, settings, weak, onGrade, onFinish, onPrint }: { plan: ReturnType<typeof buildPlan>; srsQueue: ImportedStudyItem[]; mistakes: Mistake[]; daily: Daily; settings: ExamSettings; weak: WeakAnalysis; onGrade: (item: ImportedStudyItem, correct: boolean, answer?: string) => void; onFinish: () => void; onPrint: () => void }) { return <div className="grid flex-1 gap-4 py-4 lg:grid-cols-[minmax(0,1fr)_340px]"><section><Panel eyebrow="Smart Today Mode" title="今日の勉強 / आजको पढाइ"><p className="text-sm leading-6 text-[#58665c]">Prioritized by due SRS, repeated mistakes, weak vocabulary, weak kanji, weak grammar, weakest reading/listening type, and mock readiness.</p><div className="mt-3 flex flex-wrap gap-2"><button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={onPrint}>Print Daily Study Plan</button><button className="rounded-md bg-[#1d5c3b] px-3 py-2 text-sm font-bold text-white" type="button" onClick={onFinish}>Finish Today</button></div><div className="mt-4 grid gap-3 md:grid-cols-2"><StudyList title="Due SRS reviews" items={srsQueue.slice(0, settings.examWeekMode ? 12 : 20)} onGrade={onGrade} /><StudyList title="Repeated mistakes" items={plan.mistakeItems} onGrade={onGrade} /><StudyList title={settings.examWeekMode ? "Light vocab repair" : "Weak vocabulary"} items={plan.vocabulary} onGrade={onGrade} /><StudyList title={settings.examWeekMode ? "Light kanji repair" : "Weak kanji"} items={plan.kanji} onGrade={onGrade} /><StudyList title="Weak grammar" items={plan.grammar} onGrade={onGrade} /><StudyList title="Weakest reading type" items={plan.reading} onGrade={onGrade} /><StudyList title="Weakest listening type" items={plan.listening} onGrade={onGrade} />{weak.behindTarget ? <StudyList title="Mini mock because target is behind" items={plan.mock} onGrade={onGrade} /> : null}</div></Panel></section><aside className="space-y-4"><Panel title="Daily streak"><p className="text-4xl font-bold text-[#1d5c3b]">{daily.streak}</p><p className="text-sm text-[#58665c]">Last finished: {daily.lastFinishedDate || "Not yet"}</p></Panel><Panel title="Weak Point"><p className="text-sm leading-6 text-[#58665c]">Reading: {weak.weakestReadingType}. Listening: {weak.weakestListeningType}. Worst score section: {weak.worstSection}.</p></Panel><Panel title="Mistake review"><div className="grid gap-2">{mistakes.slice(0, 8).map((mistake) => <div key={mistake.id} className="rounded-md border border-[#d9e2da] bg-[#fbfdfb] p-2 text-sm"><strong>{mistake.prompt}</strong><p className="text-[#58665c]">Expected: {mistake.expected}</p></div>)}</div></Panel>{settings.examWeekMode ? <Panel title="Exam-day checklist"><ul className="grid gap-1 text-sm text-[#58665c]"><li>Admission voucher and ID</li><li>HB pencils, eraser, watch if allowed</li><li>Route, train time, room number</li><li>Sleep, water, light review only</li></ul></Panel> : null}</aside></div>; }
function StudyList({ title, items, onGrade }: { title: string; items: ImportedStudyItem[]; onGrade: (item: ImportedStudyItem, correct: boolean, answer?: string) => void }) { return <div className="rounded-lg border border-[#d9e2da] bg-[#fbfdfb] p-3"><h3 className="font-bold text-[#1d5c3b]">{title}</h3><div className="mt-2 grid gap-2">{items.slice(0, 12).map((item) => <div key={item.id} className="rounded-md bg-white p-2 text-sm"><strong>{item.term}</strong>{item.reading ? <span className="text-[#4d745d]"> · {item.reading}</span> : null}<p className="text-[#58665c]">{item.meaning || item.meaning_np || item.explanation || item.question || item.correct_answer}</p><div className="mt-2 flex gap-2"><button className="rounded-md border border-[#b9c8bc] px-2 py-1 text-xs font-bold text-[#1d5c3b]" type="button" onClick={() => onGrade(item, true)}>Known</button><button className="rounded-md border border-[#d6b5ad] px-2 py-1 text-xs font-bold text-[#914532]" type="button" onClick={() => onGrade(item, false)}>Wrong</button></div></div>)}{!items.length ? <p className="text-sm text-[#617069]">No urgent items. Keep review light.</p> : null}</div></div>; }

function ExamModePage({ attempts, settings, weak, readiness, onSettings, onSaveAttempt }: { attempts: ExamAttempt[]; settings: ExamSettings; weak: WeakAnalysis; readiness: ReturnType<typeof calcReadiness>; onSettings: (next: ExamSettings | ((current: ExamSettings) => ExamSettings)) => void; onSaveAttempt: (scores: { language: number; reading: number; listening: number; notes: string }) => void }) {
  const [phase, setPhase] = useState<"language-reading" | "listening" | "result">("language-reading");
  const [running, setRunning] = useState(false);
  const [seconds, setSeconds] = useState(105 * 60);
  const [language, setLanguage] = useState(52);
  const [reading, setReading] = useState(50);
  const [listening, setListening] = useState(48);
  const [notes, setNotes] = useState("");
  useEffect(() => { if (!running) return; const id = window.setInterval(() => setSeconds((current) => Math.max(0, current - 1)), 1000); return () => window.clearInterval(id); }, [running]);
  useEffect(() => { if (seconds === 0 && running) { setRunning(false); if (phase === "language-reading") { setPhase("listening"); setSeconds(50 * 60); } else setPhase("result"); } }, [seconds, running, phase]);
  const total = language + reading + listening;
  const pass = total >= 90 && language >= 19 && reading >= 19 && listening >= 19;
  const target150 = total >= 150 && language >= 45 && reading >= 45 && listening >= 45;
  return <div className="grid gap-4 py-4 lg:grid-cols-[minmax(0,1fr)_360px]"><section className="space-y-4"><Panel eyebrow="Full Exam Simulation" title="JLPT N2 Exam Mode"><div className="grid gap-3 sm:grid-cols-3"><Metric label="Language + Reading" value="105 min" /><Metric label="Listening" value="50 min" /><Metric label="Strict pause" value={settings.strictMode ? "Disabled" : "Allowed"} /></div><div className="mt-4 rounded-lg border border-[#d9e2da] bg-[#fbfdfb] p-4 text-center"><p className="text-sm font-bold uppercase tracking-[0.12em] text-[#4d745d]">{phase === "language-reading" ? "Language Knowledge + Reading" : phase === "listening" ? "Listening" : "Score input"}</p><p className="mt-2 font-mono text-5xl font-bold text-[#1d5c3b] sm:text-6xl">{formatTime(seconds)}</p><div className="mt-4 flex flex-wrap justify-center gap-2"><button className="rounded-md bg-[#1d5c3b] px-4 py-2 text-sm font-bold text-white" type="button" onClick={() => setRunning(true)}>{running ? "Running" : "Start section"}</button>{!settings.strictMode ? <button className="rounded-md border border-[#b9c8bc] px-4 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={() => setRunning(false)}>Pause</button> : null}<button className="rounded-md border border-[#b9c8bc] px-4 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={() => { setRunning(false); setPhase("listening"); setSeconds(50 * 60); }}>Go Listening</button><button className="rounded-md border border-[#d6b5ad] px-4 py-2 text-sm font-bold text-[#914532]" type="button" onClick={() => { setRunning(false); setPhase("language-reading"); setSeconds(105 * 60); }}>Reset</button></div></div></Panel><Panel title="Score input and result"><div className="grid gap-3 sm:grid-cols-3"><NumberField label="Language Knowledge" value={language} onChange={setLanguage} /><NumberField label="Reading" value={reading} onChange={setReading} /><NumberField label="Listening" value={listening} onChange={setListening} /></div><label className="mt-3 block text-sm font-bold text-[#26352b]">Exam notes<textarea className="mt-1 min-h-20 w-full rounded-md border px-3 py-2" value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Mistake causes, tired section, repair notes" /></label><div className="mt-3 grid gap-2 text-sm"><p className="font-bold">Total: {total}/180</p><p>Pass check: {pass ? "Pass" : "Not yet"} · total 90+ and every section 19+</p><p>150+ target: {target150 ? "Met" : "Repair needed"} · total 150+ and every section 45+</p><p>Ideal target: Language Knowledge 52, Reading 50, Listening 48.</p><button className="rounded-md bg-[#1d5c3b] px-4 py-2 text-sm font-bold text-white" type="button" onClick={() => onSaveAttempt({ language, reading, listening, notes })}>Save attempt history</button></div></Panel></section><aside className="space-y-4"><Panel title="Exam settings"><label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={settings.strictMode} onChange={(event) => onSettings((current) => ({ ...current, strictMode: event.target.checked }))} />Strict mode: pause disabled</label><label className="mt-2 flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={settings.examWeekMode} onChange={(event) => onSettings((current) => ({ ...current, examWeekMode: event.target.checked }))} />Exam Week Mode</label><Field label="Days until exam" value={settings.daysUntilExam} onChange={(daysUntilExam) => onSettings((current) => ({ ...current, daysUntilExam }))} /></Panel><Panel title="After-exam repair"><p className="text-sm leading-6 text-[#58665c]">Weakest score section: {weak.worstSection}. Current estimated total: {readiness.total}/180.</p><ol className="mt-2 grid gap-1 text-sm text-[#334238]">{buildSevenDayPlan(weak).slice(0, 4).map((line) => <li key={line}>{line}</li>)}</ol></Panel><AttemptHistory attempts={attempts} /></aside></div>;
}
function NumberField({ label, value, onChange }: { label: string; value: number; onChange: (value: number) => void }) { return <label className="block text-sm font-bold text-[#26352b]">{label}<input className="mt-1 w-full rounded-md border px-3 py-2" type="number" min="0" max="60" value={value} onChange={(event) => onChange(Math.max(0, Math.min(60, Number(event.target.value))))} /></label>; }
function AttemptHistory({ attempts }: { attempts: ExamAttempt[] }) { return <Panel title="Attempt history"><div className="grid gap-2">{attempts.slice(0, 8).map((attempt) => <div key={attempt.id} className="rounded-md border border-[#d9e2da] bg-[#fbfdfb] p-2 text-sm"><strong>{attempt.total}/180</strong><p className="text-[#58665c]">LK {attempt.languageScore}, R {attempt.readingScore}, L {attempt.listeningScore} · {attempt.target150 ? "150+" : attempt.pass ? "pass" : "repair"}</p></div>)}{!attempts.length ? <p className="text-sm text-[#58665c]">No saved exam attempts yet.</p> : null}</div></Panel>; }

function RepairPlanPage({ weak, settings, plan, onPrint }: { weak: WeakAnalysis; settings: ExamSettings; plan: ReturnType<typeof buildPlan>; onPrint: () => void }) { return <div className="grid gap-4 py-4 lg:grid-cols-[minmax(0,1fr)_360px]"><section className="space-y-4"><Panel eyebrow="Auto Repair Plan" title="7-day weak-point repair"><button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={onPrint}>Print repair plan</button><div className="mt-4 grid gap-3">{buildSevenDayPlan(weak).map((line, index) => <div key={line} className="rounded-lg border border-[#d9e2da] bg-[#fbfdfb] p-3"><p className="text-xs font-bold uppercase tracking-[0.1em] text-[#4d745d]">Day {index + 1}</p><p className="mt-1 text-sm font-semibold text-[#26352b]">{line}</p></div>)}</div></Panel><WeakPointPanel weak={weak} /></section><aside className="space-y-4"><Panel title="Today from repair plan"><StudyList title="Language repair" items={[...plan.vocabulary, ...plan.kanji, ...plan.grammar].slice(0, 12)} onGrade={() => undefined} /><StudyList title="Reading/listening repair" items={[...plan.reading, ...plan.listening, ...plan.mock].slice(0, 8)} onGrade={() => undefined} /></Panel><Panel title="Weekly target"><p className="text-sm leading-6 text-[#58665c]">Days until exam: {settings.daysUntilExam || "Set in Settings"}. Weekly goal: raise {weak.worstSection} by 3-5 points, clear repeated mistakes, and complete one timed mini mock.</p></Panel></aside></div>; }
function WeakPointPanel({ weak }: { weak: WeakAnalysis }) { return <Panel eyebrow="Weak Point Intelligence" title="Weak lists"><div className="grid gap-3 md:grid-cols-3"><WeakColumn title="Weakest 50 Vocabulary" items={weak.vocabulary.slice(0, 50)} /><WeakColumn title="Weakest 30 Kanji" items={weak.kanji.slice(0, 30)} /><WeakColumn title="Weakest 20 Grammar" items={weak.grammar.slice(0, 20)} /></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><Metric label="Weakest reading type" value={weak.weakestReadingType} /><Metric label="Weakest listening type" value={weak.weakestListeningType} /></div></Panel>; }
function WeakColumn({ title, items }: { title: string; items: ImportedStudyItem[] }) { return <div className="rounded-lg border border-[#d9e2da] bg-[#fbfdfb] p-3"><h3 className="font-bold text-[#1d5c3b]">{title}</h3><ol className="mt-2 grid max-h-80 gap-1 overflow-auto text-sm text-[#334238]">{items.map((item) => <li key={item.id}>{item.term}{item.reading ? " · " + item.reading : ""}</li>)}</ol></div>; }

/* Module pages */
type ModuleProps = { module: JlptN2SourceCategory; items: ImportedStudyItem[]; allItems: ImportedStudyItem[]; sources: JlptN2Source[]; progress: Record<string, Progress>; selected?: ImportedStudyItem; mode: StudyMode; search: string; filter: StatusFilter; answer: string; message: string; itemDraft: ImportedStudyItem; editingItemId: string | null; showScript: boolean; dictation: string; readingSeconds: number; timerStartedAt: number | null; onSetModule: (module: JlptN2SourceCategory) => void; onSetMode: (mode: StudyMode) => void; onSearch: (value: string) => void; onFilter: (filter: StatusFilter) => void; onSelect: (id: string) => void; onAnswer: (value: string) => void; onCheck: (item: ImportedStudyItem) => void; onGrade: (item: ImportedStudyItem, correct: boolean, answer?: string) => void; onExtractWord: (word: string, sourceItem: ImportedStudyItem) => void; onDraft: (item: ImportedStudyItem) => void; onSaveItem: (event: FormEvent<HTMLFormElement>) => void; onEditItem: (item: ImportedStudyItem) => void; onDeleteItem: (id: string) => void; onToggleScript: () => void; onDictation: (value: string) => void; onStartTimer: () => void; onStopTimer: () => void; onPrintWeak: () => void };
function ModulePage(props: ModuleProps) { const meta = MODULES.find((item) => item.id === props.module) ?? MODULES[0]; return <div className="grid flex-1 gap-4 py-4 lg:grid-cols-[minmax(0,1fr)_360px]"><section className="space-y-4"><Panel eyebrow={meta.label + " module"} title={meta.japaneseLabel}><p className="text-sm leading-6 text-[#58665c]">{meta.description}</p><ModuleTabs active={props.module} onChange={props.onSetModule} /><div className="mt-4 flex flex-wrap gap-2">{(["cards", "flashcards", "quiz"] as const).map((studyMode) => <button key={studyMode} className={["rounded-md border px-3 py-2 text-sm font-bold", props.mode === studyMode ? "border-[#1d5c3b] bg-[#1d5c3b] text-white" : "border-[#b9c8bc] text-[#1d5c3b]"].join(" ")} type="button" onClick={() => props.onSetMode(studyMode)}>{studyMode}</button>)}<button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={props.onPrintWeak}>Print weak list</button></div></Panel><StudyTools {...props} /></section><aside className="space-y-4"><ItemEditor module={props.module} draft={props.itemDraft} editingId={props.editingItemId} onDraft={props.onDraft} onSave={props.onSaveItem} /><ExternalLinks sources={props.sources} />{props.selected ? <DetailTools {...props} item={props.selected} /> : null}</aside></div>; }
function ModuleTabs({ active, onChange }: { active: JlptN2SourceCategory; onChange: (module: JlptN2SourceCategory) => void }) { return <div className="mt-4 flex flex-wrap gap-2">{MODULES.filter((item) => !["mistakes", "srs"].includes(item.id)).map((module) => <button key={module.id} className={["rounded-md border px-3 py-2 text-xs font-bold", active === module.id ? "border-[#1d5c3b] bg-[#1d5c3b] text-white" : "border-[#b9c8bc] text-[#1d5c3b]"].join(" ")} type="button" onClick={() => onChange(module.id)}>{module.japaneseLabel}</button>)}</div>; }
function StudyTools(props: ModuleProps) { const visibleItems = props.items.slice(0, 80); return <Panel title="Study workspace"><div className="grid gap-3 sm:grid-cols-[minmax(0,1fr)_160px]"><input className="rounded-md border px-3 py-2" value={props.search} onChange={(event) => props.onSearch(event.target.value)} placeholder="Search term, reading, meaning, notes" /><select className="rounded-md border px-3 py-2" value={props.filter} onChange={(event) => props.onFilter(event.target.value as StatusFilter)}><option value="all">All</option><option value="known">Known</option><option value="unknown">Unknown</option><option value="due">SRS due</option></select></div>{props.mode === "flashcards" && props.selected ? <Flashcard item={props.selected} onGrade={props.onGrade} /> : null}{props.mode === "quiz" && props.selected ? <QuizBox item={props.selected} answer={props.answer} message={props.message} onAnswer={props.onAnswer} onCheck={props.onCheck} /> : null}{props.mode === "cards" ? <div className="mt-4 grid gap-3 md:grid-cols-2">{props.items.length > visibleItems.length ? <p className="rounded-md border border-[#d9e2da] bg-[#fbfdfb] p-2 text-sm text-[#58665c] md:col-span-2">Showing first {visibleItems.length} of {props.items.length}. Use search/filter for the rest.</p> : null}{visibleItems.map((item) => <Card key={item.id} item={item} progress={getProgress(item.id, props.progress)} onSelect={() => props.onSelect(item.id)} onEdit={() => props.onEditItem(item)} onDelete={() => props.onDeleteItem(item.id)} onKnown={() => props.onGrade(item, true)} onUnknown={() => props.onGrade(item, false)} />)}{!props.items.length ? <p className="text-sm text-[#58665c]">No matching items yet.</p> : null}</div> : null}{props.module === "mock test" ? <MockTrainingSummary items={props.items} /> : null}{props.module === "kanji" ? <KanjiExpansion items={props.items} allItems={props.allItems} /> : null}</Panel>; }
function Flashcard({ item, onGrade }: { item: ImportedStudyItem; onGrade: (item: ImportedStudyItem, correct: boolean) => void }) { return <div className="mt-4 rounded-lg border border-[#d9e2da] bg-[#fbfdfb] p-5"><p className="text-xs font-bold uppercase tracking-[0.12em] text-[#4d745d]">Flashcard</p><p className="mt-2 text-3xl font-bold">{item.term}</p><p className="mt-2 text-lg text-[#1d5c3b]">{item.reading}</p><p className="mt-3 text-sm leading-6 text-[#58665c]">{expected(item)}</p><div className="mt-4 flex gap-2"><button className="rounded-md bg-[#1d5c3b] px-4 py-2 text-sm font-bold text-white" type="button" onClick={() => onGrade(item, true)}>Known</button><button className="rounded-md border border-[#d6b5ad] px-4 py-2 text-sm font-bold text-[#914532]" type="button" onClick={() => onGrade(item, false)}>Wrong</button></div></div>; }
function QuizBox({ item, answer, message, onAnswer, onCheck }: { item: ImportedStudyItem; answer: string; message: string; onAnswer: (value: string) => void; onCheck: (item: ImportedStudyItem) => void }) { return <div className="mt-4 rounded-lg border border-[#d9e2da] bg-[#fbfdfb] p-4"><p className="text-sm font-bold text-[#4d745d]">{item.module === "kanji" ? "Reading quiz / meaning quiz" : item.module === "grammar" ? "Explain the meaning or use" : "Type reading or meaning"}</p><p className="mt-2 text-2xl font-bold">{item.term}</p><input className="mt-4 w-full rounded-md border px-3 py-2" value={answer} onChange={(event) => onAnswer(event.target.value)} placeholder="Type reading or meaning" /><button className="mt-3 rounded-md bg-[#1d5c3b] px-4 py-2 text-sm font-bold text-white" type="button" onClick={() => onCheck(item)}>Check answer</button>{message ? <p className="mt-2 text-sm font-semibold text-[#1d5c3b]">{message}</p> : null}</div>; }
function DetailTools(props: ModuleProps & { item: ImportedStudyItem }) { const item = props.item; return <Panel title="Practice detail"><FeatureMeta item={item} />{item.module === "reading" ? <ReadingPractice item={item} onExtract={props.onExtractWord} onStart={props.onStartTimer} onStop={props.onStopTimer} seconds={props.readingSeconds} /> : null}{item.module === "listening" ? <ListeningPractice item={item} showScript={props.showScript} dictation={props.dictation} onToggle={props.onToggleScript} onDictation={props.onDictation} /> : null}<Review item={item} onGrade={props.onGrade} answer={props.answer} /></Panel>; }
function ReadingPractice({ item, onExtract, onStart, onStop, seconds }: { item: ImportedStudyItem; onExtract: (word: string, item: ImportedStudyItem) => void; onStart: () => void; onStop: () => void; seconds: number }) { const passage = item.passage_jp || item.example_jp || item.example || ""; const words = (item.vocabulary_notes || item.related_kanji || "").split(/[,、]/).map((word) => word.trim()).filter(Boolean).slice(0, 10); return <div className="mt-3 rounded-md border border-[#d9e2da] bg-[#fbfdfb] p-3"><div className="flex flex-wrap gap-2"><button className="rounded-md bg-[#1d5c3b] px-3 py-2 text-xs font-bold text-white" type="button" onClick={onStart}>Start timer</button><button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-xs font-bold text-[#1d5c3b]" type="button" onClick={onStop}>Stop: {seconds}s</button></div><p className="mt-3 whitespace-pre-wrap text-sm leading-7">{passage}</p><div className="mt-3 flex flex-wrap gap-2">{words.map((word) => <button key={word} className="rounded-md border border-[#b9c8bc] px-2 py-1 text-xs font-bold text-[#1d5c3b]" type="button" onClick={() => onExtract(word, item)}>{word} +SRS</button>)}</div></div>; }
function ListeningPractice({ item, showScript, dictation, onToggle, onDictation }: { item: ImportedStudyItem; showScript: boolean; dictation: string; onToggle: () => void; onDictation: (value: string) => void }) { const script = item.script_jp || item.example_jp || item.example || ""; return <div className="mt-3 rounded-md border border-[#d9e2da] bg-[#fbfdfb] p-3"><button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-xs font-bold text-[#1d5c3b]" type="button" onClick={onToggle}>{showScript ? "Hide script" : "Show script"}</button>{showScript ? <p className="mt-3 whitespace-pre-wrap text-sm leading-7">{script}</p> : <p className="mt-3 text-sm text-[#58665c]">Script hidden for listening practice.</p>}<textarea className="mt-3 min-h-24 w-full rounded-md border px-3 py-2" value={dictation} onChange={(event) => onDictation(event.target.value)} placeholder="Dictation box" /><p className="mt-2 text-xs text-[#617069]">Dictation target: {item.dictation_text}</p></div>; }
function Review({ item, onGrade, answer = "" }: { item: ImportedStudyItem; onGrade: (item: ImportedStudyItem, correct: boolean, answer?: string) => void; answer?: string }) { return <div className="mt-3 rounded-md border border-[#d9e2da] bg-[#fbfdfb] p-3"><p className="text-sm font-bold">Question review</p><p className="mt-1 text-sm text-[#58665c]">{item.question || item.meaning || item.explanation || "Summarize the main point in your own words."}</p><div className="mt-2 flex gap-2"><button className="rounded-md bg-[#1d5c3b] px-3 py-2 text-xs font-bold text-white" type="button" onClick={() => onGrade(item, true, answer)}>Correct</button><button className="rounded-md border border-[#d6b5ad] px-3 py-2 text-xs font-bold text-[#914532]" type="button" onClick={() => onGrade(item, false, answer)}>Wrong</button></div></div>; }
function Card({ item, progress, onSelect, onEdit, onDelete, onKnown, onUnknown }: { item: ImportedStudyItem; progress: Progress; onSelect: () => void; onEdit: () => void; onDelete: () => void; onKnown: () => void; onUnknown: () => void }) { return <article className="rounded-lg border border-[#d9e2da] bg-[#fbfdfb] p-3"><div className="flex items-start justify-between gap-3"><div><h3 className="break-words text-lg font-bold text-[#152318]">{item.term}</h3>{item.reading ? <p className="text-sm text-[#4d745d]">{item.reading}</p> : null}</div><span className="rounded-md bg-white px-2 py-1 text-xs font-bold text-[#53625a]">{progress.status}</span></div>{item.meaning ? <p className="mt-2 text-sm text-[#334238]">{item.meaning}</p> : null}<FeatureMeta item={item} />{item.explanation ? <p className="mt-2 text-sm leading-6 text-[#334238]">{item.explanation}</p> : null}{item.example ? <p className="mt-2 rounded-md bg-white p-3 text-sm leading-6 text-[#26352b]">{item.example}</p> : null}<div className="mt-3 flex flex-wrap gap-2"><button className="rounded-md border border-[#b9c8bc] px-2 py-1 text-xs font-bold text-[#1d5c3b]" type="button" onClick={onSelect}>Study</button><button className="rounded-md border border-[#b9c8bc] px-2 py-1 text-xs font-bold text-[#1d5c3b]" type="button" onClick={onKnown}>Known</button><button className="rounded-md border border-[#d6b5ad] px-2 py-1 text-xs font-bold text-[#914532]" type="button" onClick={onUnknown}>Unknown</button><button className="rounded-md border border-[#b9c8bc] px-2 py-1 text-xs font-bold text-[#1d5c3b]" type="button" onClick={onEdit}>Edit</button><button className="rounded-md border border-[#d6b5ad] px-2 py-1 text-xs font-bold text-[#914532]" type="button" onClick={onDelete}>Delete</button></div><p className="mt-2 text-xs text-[#617069]">Due: {progress.dueDate} · Right {progress.right} / Wrong {progress.wrong}</p></article>; }
function KanjiExpansion({ items, allItems }: { items: ImportedStudyItem[]; allItems: ImportedStudyItem[] }) { return <div className="mt-4 rounded-lg border border-[#d9e2da] bg-[#f8fbf8] p-4"><h3 className="text-lg font-bold">Kanji → Vocabulary Expansion</h3><p className="mt-1 text-sm leading-6 text-[#58665c]">Vocabulary below is pulled only from your app database and original starter data.</p><div className="mt-3 grid gap-3 md:grid-cols-2">{items.filter((item) => item.module === "kanji").slice(0, 10).map((kanji) => { const matches = getVocabularyForKanji(kanji.term, allItems); return <div key={kanji.id} className="rounded-md border border-[#d6e0d8] bg-white p-3"><div className="text-xl font-bold">{kanji.term}</div>{matches.length ? <div className="mt-2 flex flex-wrap gap-2">{matches.slice(0, 10).map((match) => <span key={match.id} className="rounded-md bg-[#e9f5ee] px-2 py-1 text-sm font-semibold text-[#1d5c3b]">{match.term}</span>)}</div> : <p className="mt-2 text-sm font-semibold text-[#7a5b1d]">No imported vocabulary yet. Add legal CSV/import data.</p>}</div>; })}</div></div>; }
function FeatureMeta({ item }: { item: ImportedStudyItem }) { const lines = [(item.nepali_meaning || item.meaning_np) && "नेपाली: " + (item.nepali_meaning || item.meaning_np), (item.english_meaning || item.meaning_en) && "English: " + (item.english_meaning || item.meaning_en), item.jlpt_estimated_level && "Level: " + item.jlpt_estimated_level + (item.level_confidence ? " (" + item.level_confidence + ")" : ""), item.priority_score && "Priority: " + item.priority_score, item.tags && "Tags: " + item.tags, item.n2_purpose && "N2 purpose: " + item.n2_purpose, item.part_of_speech && "POS: " + item.part_of_speech, item.kanji_form && "Kanji: " + item.kanji_form, item.kana_form && "Kana: " + item.kana_form, item.onyomi && "Onyomi: " + item.onyomi, item.kunyomi && "Kunyomi: " + item.kunyomi, item.radicals && "Components: " + item.radicals, item.similar_kanji && "Similar kanji warning: " + item.similar_kanji, item.common_mistakes && "Common kanji mistake: " + item.common_mistakes, item.formation && "Formation: " + item.formation, item.nuance && "Nuance: " + item.nuance, item.register && "Register: " + item.register, item.usage_context && "Usage: " + item.usage_context, item.similar_patterns && "Similar grammar: " + item.similar_patterns, item.similar_words && "Similar: " + item.similar_words, item.collocations && "Collocations: " + item.collocations, item.common_mistake && "Common mistake: " + item.common_mistake, item.related_kanji && "Related kanji: " + item.related_kanji, item.example_words && "Local examples: " + item.example_words, item.n2_priority_words && "N2 words: " + item.n2_priority_words, item.passage_type && "Reading type: " + item.passage_type, item.target_time_seconds && "Target seconds: " + item.target_time_seconds, item.question_type && "Listening type: " + item.question_type, item.conversation_type && "Scene: " + item.conversation_type, item.weak_section_repair && "Repair plan: " + item.weak_section_repair, item.score_strategy && "Score rule: " + item.score_strategy].filter(Boolean); return lines.length ? <div className="mt-2 grid gap-1 text-xs text-[#617069]">{lines.map((line) => <span key={String(line)}>{line}</span>)}</div> : null; }
function ItemEditor({ module, draft, editingId, onDraft, onSave }: { module: JlptN2SourceCategory; draft: ImportedStudyItem; editingId: string | null; onDraft: (item: ImportedStudyItem) => void; onSave: (event: FormEvent<HTMLFormElement>) => void }) { const active = draft.module === module ? draft : { ...draft, module }; return <Panel title={editingId ? "Edit item" : "Add " + module}><form className="space-y-3" onSubmit={onSave}><Field label="Term" value={active.term} onChange={(term) => onDraft({ ...active, term })} /><Field label="Reading" value={active.reading ?? ""} onChange={(reading) => onDraft({ ...active, reading })} /><Field label="Meaning / answer" value={active.meaning ?? ""} onChange={(meaning) => onDraft({ ...active, meaning })} /><label className="block text-sm font-bold text-[#26352b]">Explanation / passage notes<textarea className="mt-1 min-h-20 w-full rounded-md border px-3 py-2" value={active.explanation ?? ""} onChange={(event) => onDraft({ ...active, explanation: event.target.value })} /></label><label className="block text-sm font-bold text-[#26352b]">Example / passage / script<textarea className="mt-1 min-h-24 w-full rounded-md border px-3 py-2" value={active.example ?? ""} onChange={(event) => onDraft({ ...active, example: event.target.value })} /></label><Field label="Source name" value={active.source_name ?? ""} onChange={(source_name) => onDraft({ ...active, source_name })} /><Field label="Source URL" value={active.source_url ?? ""} onChange={(source_url) => onDraft({ ...active, source_url })} /><label className="block text-sm font-bold text-[#26352b]">Advanced fields<textarea className="mt-1 min-h-20 w-full rounded-md border px-3 py-2" value={active.user_notes ?? ""} onChange={(event) => onDraft({ ...active, user_notes: event.target.value })} placeholder="Nepali meaning, collocations, radicals, formation, nuance, register, audio URL, weak point notes" /></label><button className="w-full rounded-md bg-[#1d5c3b] px-4 py-2 text-sm font-bold text-white" type="submit">{editingId ? "Save item" : "Add item"}</button></form></Panel>; }
function Field({ label, value, onChange, type = "text" }: { label: string; value: string; onChange: (value: string) => void; type?: string }) { return <label className="block text-sm font-bold text-[#26352b]">{label}<input className="mt-1 w-full rounded-md border px-3 py-2" type={type} value={value} onChange={(event) => onChange(event.target.value)} /></label>; }
function ExternalLinks({ sources }: { sources: JlptN2Source[] }) { return <Panel title="External Study Links"><div className="grid gap-2">{sources.slice(0, 8).map((source) => <a key={source.id} className="rounded-md border border-[#d4ded6] px-3 py-2 text-sm font-bold text-[#1d5c3b]" href={source.url || "/jlpt-n2/sources"} target={source.url ? "_blank" : undefined} rel={source.url ? "noreferrer" : undefined}>{source.name}</a>)}</div></Panel>; }
function MockTrainingSummary({ items }: { items: ImportedStudyItem[] }) { const rows = items.map((item) => ({ item, language: Number(item.language_score || 0), reading: Number(item.reading_score || 0), listening: Number(item.listening_score || 0) })).filter((row) => row.language || row.reading || row.listening); const last = rows[0]; if (!last) return <Panel title="Mock test scoring"><p className="text-sm text-[#58665c]">Add mock results to see score logic.</p></Panel>; const total = last.language + last.reading + last.listening; const pass = total >= 90 && last.language >= 19 && last.reading >= 19 && last.listening >= 19; const target = total >= 150 && last.language >= 45 && last.reading >= 45 && last.listening >= 45; const avg = Math.round(rows.slice(0, 5).reduce((sum, row) => sum + row.language + row.reading + row.listening, 0) / Math.max(1, rows.slice(0, 5).length)); return <Panel title="Mock test scoring"><div className="grid gap-2 text-sm"><p>Last 5 mock average: {avg}/180</p><p>Language Knowledge: {last.language}/60</p><p>Reading: {last.reading}/60</p><p>Listening: {last.listening}/60</p><p className="font-bold">Total: {total}/180</p><p>Pass rule: {pass ? "pass" : "not yet"} (total 90+, each section 19+)</p><p>150+ target: {target ? "met" : "repair plan needed"} (total 150+, each section 45+)</p><p>Ideal target: Language 52, Reading 50, Listening 48.</p><p className="text-[#58665c]">Next 7-day repair plan: redo weakest section, add mistakes to notebook, clear SRS, then retake a short mock.</p></div></Panel>; }
function MistakesPage({ mistakes, items, onPrint }: { mistakes: Mistake[]; items: ImportedStudyItem[]; onPrint: () => void }) { return <Panel eyebrow="Mistakes" title="Wrong answer log"><button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={onPrint}>Print mistake report</button><div className="mt-4 grid gap-3 md:grid-cols-2">{mistakes.slice(0, 120).map((mistake) => { const item = items.find((candidate) => candidate.id === mistake.itemId); return <div key={mistake.id} className="rounded-lg border border-[#d9e2da] bg-[#fbfdfb] p-3"><p className="text-xs font-bold uppercase tracking-[0.1em] text-[#4d745d]">{mistake.module}</p><h3 className="mt-1 font-bold">{mistake.prompt}</h3><p className="mt-2 text-sm text-[#914532]">Your answer: {mistake.answer}</p><p className="text-sm text-[#1d5c3b]">Expected: {mistake.expected}</p>{item?.example ? <p className="mt-2 rounded-md bg-white p-2 text-sm">{item.example}</p> : null}</div>; })}</div></Panel>; }
function SettingsPage(props: { importModule: JlptN2SourceCategory; importText: string; preview: ImportPreview; settings: ExamSettings; message: string; restoreText: string; onSettings: (next: ExamSettings | ((current: ExamSettings) => ExamSettings)) => void; onImportModule: (module: JlptN2SourceCategory) => void; onImportText: (value: string) => void; onFile: (event: ChangeEvent<HTMLInputElement>) => void; onPreview: (event: FormEvent<HTMLFormElement>) => void; onSavePreview: () => void; onTemplate: (module: JlptN2SourceCategory) => void; onGenerate: () => void; onPrintGrammar: () => void; onPrintMock: () => void; onBackup: () => void; onRestoreText: (value: string) => void; onRestore: () => void }) { return <div className="grid gap-4 py-4 lg:grid-cols-[minmax(0,1fr)_360px]"><Panel eyebrow="Import / export" title="CSV and JSON tools"><form className="space-y-3" onSubmit={props.onPreview}><label className="block text-sm font-bold text-[#26352b]">Module<select className="mt-1 w-full rounded-md border px-3 py-2" value={props.importModule} onChange={(event) => props.onImportModule(event.target.value as JlptN2SourceCategory)}>{MODULES.map((module) => <option key={module.id} value={module.id}>{module.label} ({module.importFile})</option>)}</select></label><input className="w-full rounded-md border px-3 py-2" type="file" accept=".csv,.json,text/csv,application/json" onChange={props.onFile} /><textarea className="min-h-36 w-full rounded-md border px-3 py-2 font-mono text-xs" value={props.importText} onChange={(event) => props.onImportText(event.target.value)} placeholder={templates[props.importModule]} /><div className="flex flex-wrap gap-2"><button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={() => props.onTemplate(props.importModule)}>Download template</button><button className="rounded-md bg-[#1d5c3b] px-3 py-2 text-sm font-bold text-white" type="button" onClick={props.onBackup}>Export Full Backup</button><button className="rounded-md bg-[#1d5c3b] px-3 py-2 text-sm font-bold text-white" type="submit">Preview import</button><button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-sm font-bold text-[#1d5c3b] disabled:opacity-50" type="button" onClick={props.onSavePreview} disabled={!props.preview.rows.length || Boolean(props.preview.errors.length)}>Save preview</button></div></form><ImportPreview preview={props.preview} /></Panel><aside className="space-y-4"><Panel title="Exam Week Mode"><label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={props.settings.examWeekMode} onChange={(event) => props.onSettings((current) => ({ ...current, examWeekMode: event.target.checked }))} />Enable Exam Week Mode</label><Field label="Days until exam" value={props.settings.daysUntilExam} onChange={(daysUntilExam) => props.onSettings((current) => ({ ...current, daysUntilExam }))} /><p className="mt-2 text-sm text-[#58665c]">When enabled: no heavy new content, timed reading daily, listening daily, mistake notebook daily, mock correction, and light vocab/kanji review.</p></Panel><Panel title="Restore backup"><p className="text-sm font-semibold text-[#914532]">Warning: browser clearing can delete local progress. Restore only a backup you exported from this app.</p><textarea className="mt-2 min-h-28 w-full rounded-md border px-3 py-2 font-mono text-xs" value={props.restoreText} onChange={(event) => props.onRestoreText(event.target.value)} placeholder="Paste full backup JSON here" /><button className="mt-2 w-full rounded-md border border-[#d6b5ad] px-3 py-2 text-sm font-bold text-[#914532]" type="button" onClick={props.onRestore}>Restore Backup</button>{props.message ? <p className="mt-2 text-sm font-bold text-[#1d5c3b]">{props.message}</p> : null}</Panel><Panel title="PDF / print exports"><div className="grid gap-2"><button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={props.onPrintGrammar}>Print grammar review sheet</button><button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={props.onPrintMock}>Print mock result report</button></div></Panel></aside></div>; }
function ImportPreview({ preview }: { preview: ImportPreview }) { if (!preview.rows.length && !preview.errors.length) return null; return <div className="mt-4 rounded-lg border border-[#d9e2da] bg-[#fbfdfb] p-3"><h3 className="font-bold">Import preview</h3>{preview.errors.length ? <ul className="mt-2 grid gap-1 text-sm font-semibold text-[#914532]">{preview.errors.map((error) => <li key={error}>{error}</li>)}</ul> : <p className="mt-2 text-sm font-semibold text-[#1d5c3b]">{preview.rows.length} rows ready to save.</p>}<div className="mt-3 grid gap-2">{preview.rows.slice(0, 5).map((row) => <div key={row.id} className="rounded-md bg-white p-2 text-sm"><strong>{row.term}</strong> {row.reading} {row.meaning}</div>)}</div></div>; }
function SourcesPage({ sources, draft, editingId, onDraft, onSave, onEdit, onDelete, onCancel }: { sources: JlptN2Source[]; draft: SourceDraft; editingId: string | null; onDraft: (draft: SourceDraft) => void; onSave: (event: FormEvent<HTMLFormElement>) => void; onEdit: (source: JlptN2Source) => void; onDelete: (id: string) => void; onCancel: () => void }) { return <div className="grid gap-4 py-4 lg:grid-cols-[360px_minmax(0,1fr)]"><Panel title={editingId ? "Edit source" : "Add source link"}><form className="space-y-3" onSubmit={onSave}><Field label="Source name" value={draft.name} onChange={(name) => onDraft({ ...draft, name })} /><label className="block text-sm font-bold text-[#26352b]">Category<select className="mt-1 w-full rounded-md border px-3 py-2" value={draft.category} onChange={(event) => onDraft({ ...draft, category: event.target.value as JlptN2SourceCategory })}>{MODULES.map((module) => <option key={module.id} value={module.id}>{module.label}</option>)}</select></label><Field label="JLPT level" value={draft.level} onChange={(level) => onDraft({ ...draft, level: level as JlptN2Source["level"] })} /><Field label="URL" value={draft.url} onChange={(url) => onDraft({ ...draft, url })} /><label className="block text-sm font-bold text-[#26352b]">Notes<textarea className="mt-1 min-h-24 w-full rounded-md border px-3 py-2" value={draft.notes} onChange={(event) => onDraft({ ...draft, notes: event.target.value })} /></label><Field label="Best use" value={draft.best_use || ""} onChange={(best_use) => onDraft({ ...draft, best_use })} /><Field label="Last studied date" type="date" value={draft.lastStudiedDate} onChange={(lastStudiedDate) => onDraft({ ...draft, lastStudiedDate })} /><label className="block text-sm font-bold text-[#26352b]">Confidence / usefulness rating<input className="mt-1 w-full" type="range" min="1" max="5" value={draft.usefulnessRating} onChange={(event) => onDraft({ ...draft, usefulnessRating: Number(event.target.value) })} /><span className="text-xs text-[#58665c]">{draft.usefulnessRating}/5</span></label><label className="flex items-center gap-2 text-sm font-bold text-[#26352b]"><input type="checkbox" checked={Boolean(draft.favorite)} onChange={(event) => onDraft({ ...draft, favorite: event.target.checked })} />Favorite</label><label className="flex items-center gap-2 text-sm font-bold text-[#26352b]"><input type="checkbox" checked={draft.externalOnly} onChange={(event) => onDraft({ ...draft, externalOnly: event.target.checked })} />External-only content</label><label className="flex items-center gap-2 text-sm font-bold text-[#26352b]"><input type="checkbox" checked={draft.hasImportedPersonalNotes} onChange={(event) => onDraft({ ...draft, hasImportedPersonalNotes: event.target.checked })} />Personal notes imported</label><button className="w-full rounded-md bg-[#1d5c3b] px-4 py-2 text-sm font-bold text-white" type="submit">{editingId ? "Save Source" : "Add Source"}</button>{editingId ? <button className="w-full rounded-md border border-[#b9c8bc] px-4 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={onCancel}>Cancel</button> : null}</form></Panel><Panel eyebrow="Source Library Module" title="Reference links and user-owned notes"><div className="grid gap-3 md:grid-cols-2">{sources.map((source) => <SourceCard key={source.id} source={source} onEdit={() => onEdit(source)} onDelete={() => onDelete(source.id)} />)}</div></Panel></div>; }
function SourceCard({ source, onEdit, onDelete }: { source: JlptN2Source; onEdit: () => void; onDelete: () => void }) { return <article className="rounded-lg border border-[#d9e2da] bg-[#fbfdfb] p-3"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><h3 className="break-words text-base font-bold text-[#152318]">{source.name}</h3><p className="mt-1 text-xs font-bold uppercase tracking-[0.12em] text-[#4d745d]">{source.category} · {source.level}</p></div><span className="rounded-md bg-white px-2 py-1 text-xs font-bold text-[#53625a]">{source.usefulnessRating}/5</span></div><p className="mt-3 text-sm leading-6 text-[#4d5c52]">{source.notes}</p><p className="mt-2 text-xs text-[#617069]">Best use: {source.best_use || source.notes} · Favorite: {source.favorite ? "Yes" : "No"} · External-only: {source.externalOnly ? "Yes" : "No"} · Personal notes: {source.hasImportedPersonalNotes ? "Imported" : "Not imported"}</p><div className="mt-4 flex flex-wrap gap-2">{source.url ? <a className="rounded-md bg-[#1d5c3b] px-3 py-2 text-sm font-bold text-white" href={source.url} target="_blank" rel="noreferrer">Open Link</a> : null}<button className="rounded-md border border-[#b9c8bc] px-3 py-2 text-sm font-bold text-[#1d5c3b]" type="button" onClick={onEdit}>Edit</button><button className="rounded-md border border-[#d6b5ad] px-3 py-2 text-sm font-bold text-[#914532]" type="button" onClick={onDelete}>Delete</button></div></article>; }

function analyzeWeakPoints(items: ImportedStudyItem[], progress: Record<string, Progress>, mistakes: Mistake[], attempts: ExamAttempt[]) {
  const mistakeCount = new Map<string, number>();
  for (const mistake of mistakes) mistakeCount.set(mistake.itemId, (mistakeCount.get(mistake.itemId) ?? 0) + 2);
  const scoreItem = (item: ImportedStudyItem) => { const p = getProgress(item.id, progress); return (mistakeCount.get(item.id) ?? 0) + p.wrong * 2 + (p.status === "unknown" ? 3 : 0) + (p.srsLevel <= 1 ? 1 : 0); };
  const weakByModule = (module: JlptN2SourceCategory, limit: number) => items.filter((item) => item.module === module).map((item) => ({ item, score: scoreItem(item) })).sort((a, b) => b.score - a.score).slice(0, limit).map((row) => row.item);
  const readingTypeCounts = groupMistakeTypes(mistakes, items, "reading");
  const listeningTypeCounts = groupMistakeTypes(mistakes, items, "listening");
  const lastFive = attempts.slice(0, 5);
  const lastFiveAverage = lastFive.length ? Math.round(lastFive.reduce((sum, attempt) => sum + attempt.total, 0) / lastFive.length) : 0;
  const bestScore = attempts.length ? Math.max(...attempts.map((attempt) => attempt.total)) : 0;
  const sectionTotals = attempts.length ? [avg(attempts.map((attempt) => attempt.languageScore)), avg(attempts.map((attempt) => attempt.readingScore)), avg(attempts.map((attempt) => attempt.listeningScore))] : [0, 0, 0];
  const worstSection = attempts.length ? ["Language Knowledge", "Reading", "Listening"][sectionTotals.indexOf(Math.min(...sectionTotals))] : "No mock yet";
  const sectionTrend = attempts.length >= 2 ? (attempts[0].total >= attempts[1].total ? "rising or stable" : "falling") : "Need 2 attempts";
  const readinessPercent = attempts.length ? Math.min(100, Math.round(((lastFiveAverage || attempts[0].total) / 150) * 100)) : 0;
  return { vocabulary: weakByModule("vocabulary", 50), kanji: weakByModule("kanji", 30), grammar: weakByModule("grammar", 20), weakestReadingType: topKey(readingTypeCounts) || "short / timed purpose questions", weakestListeningType: topKey(listeningTypeCounts) || "task comprehension", lastFiveAverage, bestScore, worstSection, sectionTrend, readinessPercent, behindTarget: !lastFiveAverage || lastFiveAverage < 150 || attempts.some((attempt) => !attempt.target150) };
}
function groupMistakeTypes(mistakes: Mistake[], items: ImportedStudyItem[], module: JlptN2SourceCategory) { const counts = new Map<string, number>(); for (const mistake of mistakes.filter((item) => item.module === module)) { const source = items.find((item) => item.id === mistake.itemId); const key = module === "reading" ? source?.passage_type || source?.reading_type || "reading accuracy" : source?.question_type || source?.weakness_category || "listening accuracy"; counts.set(key, (counts.get(key) ?? 0) + 1); } return counts; }
function buildSevenDayPlan(weak: WeakAnalysis) { return ["Day 1: Language knowledge repair - review weakest vocabulary and kanji, then redo related mistakes.", "Day 2: Grammar repair - drill weakest grammar patterns and compare similar patterns.", "Day 3: Reading speed - timed " + weak.weakestReadingType + " practice with vocabulary extraction.", "Day 4: Reading accuracy - redo wrong reading questions and write why-wrong notes.", "Day 5: Listening repair - focus on " + weak.weakestListeningType + " scripts, dictation, and shadowing.", "Day 6: Listening speed - replay counters, key point notes, and quick response practice.", "Day 7: Mini mock + mistake notebook review; update score history and next weak-section target."]; }
function buildPlan(items: ImportedStudyItem[], progress: Record<string, Progress>, mistakes: Mistake[], weak: WeakAnalysis, settings: ExamSettings) { const unseen = (module: JlptN2SourceCategory, count: number) => items.filter((item) => item.module === module && getProgress(item.id, progress).status === "new").slice(0, count); const mistakeItems = mistakes.map((mistake) => items.find((item) => item.id === mistake.itemId)).filter(Boolean) as ImportedStudyItem[]; const choose = (weakItems: ImportedStudyItem[], fallbackModule: JlptN2SourceCategory, count: number) => [...weakItems, ...unseen(fallbackModule, count)].filter(uniqueItem).slice(0, count); const reading = items.filter((item) => item.module === "reading" && [item.passage_type, item.reading_type].join(" ").includes(weak.weakestReadingType)).slice(0, 1); const listening = items.filter((item) => item.module === "listening" && [item.question_type, item.weakness_category].join(" ").includes(weak.weakestListeningType)).slice(0, 1); const plan = { vocabulary: choose(weak.vocabulary, "vocabulary", settings.examWeekMode ? 6 : 10), kanji: choose(weak.kanji, "kanji", settings.examWeekMode ? 3 : 5), grammar: choose(weak.grammar, "grammar", 2), reading: reading.length ? reading : unseen("reading", 1), listening: listening.length ? listening : unseen("listening", 1), mock: items.filter((item) => item.module === "mock test").slice(0, 1), mistakeItems: mistakeItems.slice(0, 8), mistakes }; return { ...plan, all: [...plan.vocabulary, ...plan.kanji, ...plan.grammar, ...plan.reading, ...plan.listening, ...plan.mock] }; }
function calcReadiness(items: ImportedStudyItem[], progress: Record<string, Progress>, mistakes: Mistake[], attempts: ExamAttempt[]) { const score = (modules: JlptN2SourceCategory[], target: number) => { const pool = items.filter((item) => modules.includes(item.module)); const known = pool.filter((item) => getProgress(item.id, progress).status === "known").length; return Math.round(60 * (Math.min(1, pool.length / target) * 0.55 + (pool.length ? known / pool.length : 0) * 0.45)); }; const attemptBoost = attempts[0] ? attempts[0] : null; const language = attemptBoost ? Math.round((score(["vocabulary", "kanji", "grammar"], 2530) + attemptBoost.languageScore) / 2) : score(["vocabulary", "kanji", "grammar"], 2530); const reading = attemptBoost ? Math.round((score(["reading"], 300) + attemptBoost.readingScore) / 2) : score(["reading"], 300); const listening = attemptBoost ? Math.round((score(["listening"], 300) + attemptBoost.listeningScore) / 2) : score(["listening"], 300); const weakest = MODULES.map((module) => ({ label: module.label, count: mistakes.filter((mistake) => mistake.module === module.id).length })).sort((a, b) => b.count - a.count)[0]; return { language, reading, listening, total: language + reading + listening, weakest: weakest?.count ? weakest.label : [{ label: "Language Knowledge", value: language }, { label: "Reading", value: reading }, { label: "Listening", value: listening }].sort((a, b) => a.value - b.value)[0].label }; }
function filterItems(items: ImportedStudyItem[], module: JlptN2SourceCategory, progress: Record<string, Progress>, search: string, filter: StatusFilter) { const query = search.toLowerCase().trim(); return items.filter((item) => { if (item.module !== module) return false; const p = getProgress(item.id, progress); if (filter === "known" && p.status !== "known") return false; if (filter === "unknown" && p.status !== "unknown") return false; if (filter === "due" && p.dueDate > todayIso()) return false; return !query || [item.term, item.title, item.reading, item.meaning, item.meaning_np, item.meaning_en, item.explanation, item.explanation_np, item.example, item.example_jp, item.example_np, item.passage_jp, item.script_jp, item.user_notes, item.collocations, item.similar_words, item.related_kanji, item.tags, item.n2_purpose, item.questions].join(" ").toLowerCase().includes(query); }); }
function buildSourceLibrary(): JlptN2Source[] { const names = ["Official JLPT Worldwide", "JEES MyJLPT", "JLPT official sample questions", "JLPT Sensei Kanji", "JLPT Sensei Vocabulary", "JLPT Sensei Grammar", "Bunpro Grammar", "WaniKani", "Renshuu", "MaruMori", "Satori Reader", "Yomitan", "JPDB", "Migaku", "日本語の森", "MLC Japanese", "Coto Academy", "Tofugu", "NHK News Web Easy", "Todaii Japanese", "JapaneseTest4You", "Kanshudo", "Jisho", "Takoboto", "Mazii", "iKnow Core 6000", "Anki", "Nihongo Shark", "Tae Kim", "Imabi", "Wasabi Japanese", "Maggie Sensei", "JLPT Boot Camp", "Nihongo-Pro", "Japan Foundation", "Irodori", "Minato", "Erin's Challenge", "NHK World Japan", "Easy Japanese Podcast", "Nihongo con Teppei", "The Real Japanese Podcast", "Japanese with Shun", "Comprehensible Japanese", "Meshclass", "Miku Real Japanese", "三本塾", "あかね的日本語教室", "Onomappu", "Yuyu Japanese", "Nihongo Life", "Learn Japanese with Noriko", "Sakura Tips", "JLPT N2 mock site 1", "JLPT N2 mock site 2", "JLPT N2 reading blog", "JLPT N2 listening drills", "Japanese IO", "Tangorin", "Weblio", "Goo Dictionary", "Kotobank", "Aozora Bunko", "Matcha Easy Japanese", "NHK News", "News Web Easy archive", "Hukumusume", "ChokoChoko Library", "Natively", "Bookmeter", "Tadoku free books", "多読ステーション", "Yotsuba reading notes", "AnkiWeb shared decks", "Kitsun", "Houhou SRS", "Memrise Japanese", "Quizlet N2", "Kanji Koohii", "RTK community", "KanjiVG", "Jitenon", "Kakijun", "OJAD", "Forvo", "YouGlish Japanese", "Language Reactor", "ASBPlayer", "Jimaku Player", "Subadub", "Netflix Japanese study", "YouTube teacher playlist", "My notebook", "My CSV imports", "My Anki-style data", "My school handouts", "My work vocabulary", "My city hall Japanese", "My clinic Japanese", "My interview notes", "My mock test archive", "My mistake notebook"]; const urls: Record<string, string> = { "Official JLPT Worldwide": "https://www.jlpt.jp/", "JEES MyJLPT": "https://info.jees-jlpt.jp/", "WaniKani": "https://www.wanikani.com/", "Bunpro Grammar": "https://bunpro.jp/", "Satori Reader": "https://www.satorireader.com/", "Yomitan": "https://yomitan.wiki/", "JPDB": "https://jpdb.io/", "日本語の森": "https://www.youtube.com/@nihongonomori2013", "NHK News Web Easy": "https://www3.nhk.or.jp/news/easy/", "Todaii Japanese": "https://japanese.todaiinews.com/", "Jisho": "https://jisho.org/", "Anki": "https://apps.ankiweb.net/" }; const categories: JlptN2SourceCategory[] = ["kanji", "vocabulary", "grammar", "reading", "listening", "mock test"]; const generated = names.map((name, index): JlptN2Source => ({ id: "source-100-" + index, name, category: categories[index % categories.length], level: name.startsWith("My ") ? "User" : "N2", url: urls[name] ?? "", notes: "Best use: feature inspiration, external reference, and legal personal note routing only.", best_use: "Reference coverage, workflow inspiration, or user-owned notes.", externalOnly: !name.startsWith("My "), hasImportedPersonalNotes: name.startsWith("My "), lastStudiedDate: "", usefulnessRating: index < 25 ? 5 : 3, favorite: index < 15 })); return mergeSources(STARTER_SOURCES, generated); }
function mergeSources(primary: JlptN2Source[] | null | undefined, fallback: JlptN2Source[]) { const seen = new Set<string>(); return [...(primary ?? []), ...fallback].filter((source) => { const key = source.name.toLowerCase(); if (seen.has(key)) return false; seen.add(key); return true; }).slice(0, 140); }
function isModule(input: AppView): input is JlptN2SourceCategory { return MODULES.some((item) => item.id === input); }
function getProgress(id: string, progress: Record<string, Progress>): Progress { return progress[id] ?? { status: "new", srsLevel: 0, dueDate: todayIso(), right: 0, wrong: 0 }; }
function getSrsQueue(items: ImportedStudyItem[], progress: Record<string, Progress>) { return items.filter((item) => ["vocabulary", "kanji", "grammar"].includes(item.module) && getProgress(item.id, progress).dueDate <= todayIso()).sort((a, b) => getProgress(b.id, progress).wrong - getProgress(a.id, progress).wrong).slice(0, 50); }
function expected(item: ImportedStudyItem) { return item.correct_answer || item.correct_answers || [item.reading, item.meaning, item.meaning_np, item.meaning_en, item.explanation].filter(Boolean).join(" / ") || item.term; }
function validateRows(rows: ImportedStudyItem[], module: JlptN2SourceCategory) { const errors: string[] = []; rows.forEach((row, index) => { if (!row.term) errors.push("Row " + (index + 1) + ": term is required."); if (["vocabulary", "kanji"].includes(module) && !row.meaning && !row.meaning_np) errors.push("Row " + (index + 1) + ": meaning is required."); if (module === "grammar" && !row.explanation && !row.explanation_np) errors.push("Row " + (index + 1) + ": explanation is required."); if (["reading", "listening"].includes(module) && !row.example && !row.example_jp && !row.passage_jp && !row.script_jp) errors.push("Row " + (index + 1) + ": passage/script is required."); if (row.source_url && !row.source_name) errors.push("Row " + (index + 1) + ": source_name is required when source_url is present."); }); return errors; }
function buildOriginalBatch(offset: number): ImportedStudyItem[] { const make = (module: JlptN2SourceCategory, count: number, prefix: string) => Array.from({ length: count }, (_, index): ImportedStudyItem => ({ id: "generated-" + module + "-" + offset + "-" + index, module, term: module === "kanji" ? String.fromCharCode(0x4e00 + ((offset + index) % 1800)) : prefix + " " + (index + 1), reading: module === "kanji" ? "オン / くん" : "original-" + (index + 1), meaning: "Original " + module + " meaning " + (index + 1), explanation: "Original Nepali-friendly explanation " + (index + 1) + ".", example: "これは著作権を侵害しないオリジナル例文です。", source_name: "Generated original batch", source_url: "", source_type: "original-admin-tool", copyright_status: "original", user_notes: "", created_by_user: false })); return [...make("vocabulary", 300, "Original N2 vocabulary"), ...make("kanji", 100, "Original kanji"), ...make("grammar", 50, "Original grammar pattern"), ...make("reading", 30, "Original reading passage"), ...make("listening", 30, "Original listening script")]; }
function uniqueItem(item: ImportedStudyItem, index: number, list: ImportedStudyItem[]) { return list.findIndex((candidate) => candidate.id === item.id) === index; }
function avg(values: number[]) { return values.length ? Math.round(values.reduce((sum, value) => sum + value, 0) / values.length) : 0; }
function topKey(map: Map<string, number>) { return Array.from(map.entries()).sort((a, b) => b[1] - a[1])[0]?.[0] || ""; }
function weakestFromScores(language: number, reading: number, listening: number) { const rows = [{ label: "Language Knowledge", score: language, target: 52 }, { label: "Reading", score: reading, target: 50 }, { label: "Listening", score: listening, target: 48 }]; return rows.sort((a, b) => (a.score - a.target) - (b.score - b.target))[0].label; }
function formatTime(seconds: number) { const minute = Math.floor(seconds / 60); const sec = seconds % 60; return String(minute).padStart(2, "0") + ":" + String(sec).padStart(2, "0"); }
function todayIso() { return new Date().toISOString().slice(0, 10); }
function srsDelay(stage: number) { return [0, 1, 3, 7, 14, 30, 3650][stage] ?? 1; }
function addDaysIso(days: number) { const date = new Date(); date.setDate(date.getDate() + days); return date.toISOString().slice(0, 10); }
function daysBetween(a: string, b: string) { return Math.floor((new Date(b).getTime() - new Date(a).getTime()) / 86400000); }
function readLocal<T>(key: string): T | null { try { const stored = window.localStorage.getItem(key); return stored ? JSON.parse(stored) as T : null; } catch { return null; } }
function downloadText(filename: string, text: string) { const blob = new Blob([text], { type: "application/json;charset=utf-8" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url); }
function esc(value: string) { return value.replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#039;" }[char] ?? char)); }
